<?php
/** Model-schema form: safe attributes, enum choices and validation feedback. */
use yii\helpers\Html;
$schema=$model::getTableSchema();
?>
<a href="/admin/<?= e($table) ?>">← <?= e($label) ?></a><h1><?= $model->isNewRecord?'新增':'编辑' ?><?= e($label) ?></h1><form method="post" class="form-panel admin-form"><?= csrf_field() ?><?= Html::errorSummary($model,['class'=>'form-errors']) ?><div class="form-grid"><?php foreach($model->safeAttributes() as $field): ?><?php $column=$schema->columns[$field]??null; if(!$column) {continue;} $value=$model->$field; ?><label><?= e($model->getAttributeLabel($field)) ?><small><?= e($column->comment?:$field) ?><?= $column->allowNull?' · 可空':'' ?></small><?php if($column->enumValues): ?><select name="Record[<?= e($field) ?>]"><?php foreach($column->enumValues as $v): ?><option <?= $value===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach ?></select><?php elseif(in_array($field,['status'],true)&&$table==='news_articles'): ?><select name="Record[status]"><?php foreach(['draft','published','hidden'] as $v): ?><option <?= $value===$v?'selected':'' ?>><?= e($v) ?></option><?php endforeach ?></select><?php elseif(in_array($column->type,['text','json'],true)||str_contains($field,'body')||($column->size??0)>1000): ?><textarea name="Record[<?= e($field) ?>]" rows="5"><?= e(is_string($value)?$value:($value===null?'':json_encode($value,JSON_UNESCAPED_UNICODE))) ?></textarea><?php else: ?><input name="Record[<?= e($field) ?>]" value="<?= e($value) ?>" <?= $column->size?'maxlength="'.(int)$column->size.'"':'' ?> placeholder="<?= in_array($column->type,['datetime','timestamp'],true)?'YYYY-MM-DD HH:MM:SS':e($field) ?>"><?php endif ?></label><?php endforeach ?></div><?php if($tags): ?><fieldset><legend>新闻标签</legend><div class="choice-grid"><?php foreach($tags as $tag): ?><label class="choice"><input type="checkbox" name="tag_ids[]" value="<?= (int)$tag->id ?>" <?= in_array($tag->id,$model->tagIds)?'checked':'' ?>><?= e($tag->name_cn) ?></label><?php endforeach ?></div></fieldset><?php endif ?><button class="button">保存到 MySQL →</button><p class="meta">保存后前台读取同一数据库。ID、创建时间等不可通过表单覆盖。</p></form>
